result.text:
  if (r.pendiente) {
    return `<section class="card prueba">${cabecera}
      <div class="card-body"><p class="hint">Leyendo… en cuanto termine salen aquí el texto y lo que entiendo.</p></div>
    </section>`;
  }

  if (r.error || !doc) {
    return `<section class="card prueba">${cabecera}
      <div class="card-body"><p class="prueba-error">${esc(r.error || "No he podido leerlo.")}</p></div>
    </section>`;
  }

  const filas = datosDeLectura(doc);
  const avisos = Array.isArray(doc.notes) ? doc.notes : [];
  const json = jsonDocumento(doc);

  return `<section class="card prueba">
    ${cabecera}
    <div class="card-body">
      ${
        L.reconoce
          ? ""
          : `<p class="prueba-aviso">Este papel no lo reconoce ningún lector con nombre, así que se ha mirado como documento genérico. Puede que falte algún dato: mira la lista antes de fiarte.</p>`
      }
      <dl class="prueba-datos">
        ${filas.map((f) => `<div class="prueba-fila"><dt>${esc(f.etiqueta)}</dt><dd>${esc(f.valor)}</dd></div>`).join("")}
      </dl>
      ${
        avisos.length
          ? `<div class="prueba-avisos"><strong>Lo que no me cuadra:</strong><ul>${avisos
              .map((a) => `<li>${esc(a)}</li>`)
              .join("")}</ul></div>`
          : ""
      }
      <details class="prueba-detalle">
        <summary>Ver el texto que he leído (${fmtNum(r.texto.length, 0)} caracteres)</summary>
        <pre class="prueba-texto">${esc(r.texto)}</pre>
      </details>
      <details class="prueba-detalle">
        <summary>Todos los datos tal cual</summary>
        <pre class="prueba-texto">${esc(json)}</pre>
      </details>
    </div>
  </section>`;
}

/** Los datos del documento en pares «etiqueta: valor», para la pantalla y el informe. */
function datosDeLectura(doc) {
  const filas = [];
  const pon = (etiqueta, valor) => {
    if (valor === null || valor === undefined || valor === "") return;
    filas.push({ etiqueta, valor: String(valor) });
  };
  pon("Tipo de documento", kindInfo(doc.kind).label);
  pon("Concepto", categoryInfo(doc.category).label);
  pon("¿Entra o sale dinero?", doc.direction === "INGRESO" ? "Entra (ingreso)" : "Sale (gasto)");
  pon("Número", doc.number);
  pon("Fecha", doc.issueDate ? fmtDate(doc.issueDate) : "");
  pon("Proveedor o trabajador", doc.supplierName);
  pon("NIF", doc.supplierNif);
  pon("Base imponible", doc.base ? fmtEUR(doc.base) : "");
  pon("Tipo de IGIC", Number.isFinite(doc.rate) ? `${fmtNum(doc.rate, 2)} %` : "");
  pon("Cuota de IGIC", doc.igic ? fmtEUR(doc.igic) : "");
  pon("Total", doc.total ? fmtEUR(doc.total) : "");
  pon("Estado", doc.status === STATUS.PAID ? "Cobrado o pagado" : "Pendiente");
  pon("Confianza", Number.isFinite(doc.confidence) ? `${Math.round(doc.confidence * 100)} %` : "");
  return filas;
}

/** El documento en JSON, sin el texto entero: eso ya se enseña aparte. */
function jsonDocumento(doc) {
  try {
    const copia = { ...doc };
    delete copia.rawText;
    return JSON.stringify(copia, null, 2);
  } catch (_) {
    return "";
  }
}
